void commandCatalogBindModuleCommand(commandCatalog *cat, struct redisCommand *cmd) {
    cat->module_cmd = cmd;
    cat->module_flags = cmd ? (int64_t)cmd->flags : 0;
    cat->module_flag_error = cmd ? 0 : 1;
}

int *commandCatalogPrepareKeys(commandCatalog *cat, getKeysResult *result, int numkeys) {
    cat->keys_out = result;
    cat->keys_count = result ? result->numkeys : 0;
    if (!result) return NULL;

    /* GETKEYS_RESULT_INIT initializes keys to NULL, point it to the pre-allocated stack
     * buffer here. */
    if (!result->keys) {
        serverAssert(!result->numkeys);
        result->keys = result->keysbuf;
    }

    /* Resize if necessary */
    if (numkeys > result->size) {
        if (result->keys != result->keysbuf) {
            /* We're not using a static buffer, just (re)alloc */
            result->keys = zrealloc(result->keys, numkeys * sizeof(int));
        } else {
            /* We are using a static buffer, copy its contents */
            result->keys = zmalloc(numkeys * sizeof(int));
            if (result->numkeys)
                memcpy(result->keys, result->keysbuf, result->numkeys * sizeof(int));
        }
        result->size = numkeys;
    }

    cat->keys_count = result->numkeys;
    return result->keys;
}

void commandCatalogFreeKeys(commandCatalog *cat, getKeysResult *result) {
    cat->keys_out = result;
    if (result && result->keys != result->keysbuf)
        zfree(result->keys);
    cat->keys_count = 0;
}

void commandCatalogBindKeyCommand(commandCatalog *cat, struct redisCommand *cmd, robj **argv, int argc, getKeysResult *result) {
    cat->keys_cmd = cmd;
    cat->keys_argv = argv;
    cat->keys_argc = argc;
