void commandCatalogResetModuleFlags(commandCatalog *cat) {
    cat->module_flags = 0;
    cat->module_keyspec_flags = 0;
    cat->module_flag_str = NULL;
    cat->module_flag_error = 0;
    cat->module_cmd = NULL;
    cat->module_token = NULL;
    cat->module_token_count = 0;
}

int64_t commandCatalogMapModuleFlag(commandCatalog *cat, const char *token) {
    cat->module_token = (char *)token;
    if (!token) {
        cat->module_flag_error = 1;
        return -1;
    }
    if (!strcasecmp(token,"write")) return CMD_WRITE;
    else if (!strcasecmp(token,"readonly")) return CMD_READONLY;
    else if (!strcasecmp(token,"admin")) return CMD_ADMIN;
    else if (!strcasecmp(token,"deny-oom")) return CMD_DENYOOM;
    else if (!strcasecmp(token,"deny-script")) return CMD_NOSCRIPT;
    else if (!strcasecmp(token,"allow-loading")) return CMD_LOADING;
    else if (!strcasecmp(token,"pubsub")) return CMD_PUBSUB;
    else if (!strcasecmp(token,"random")) return CMD_RANDOM;
    else if (!strcasecmp(token,"allow-stale")) return CMD_STALE;
    else if (!strcasecmp(token,"no-monitor")) return CMD_SKIP_MONITOR;
    else if (!strcasecmp(token,"no-slowlog")) return CMD_SKIP_SLOWLOG;
    else if (!strcasecmp(token,"fast")) return CMD_FAST;
    else if (!strcasecmp(token,"no-auth")) return CMD_NO_AUTH;
    else if (!strcasecmp(token,"may-replicate")) return CMD_MAY_REPLICATE;
    else if (!strcasecmp(token,"getkeys-api")) return CMD_MODULE_GETKEYS;
    else if (!strcasecmp(token,"no-cluster")) return CMD_MODULE_NO_CLUSTER;
    cat->module_flag_error = 1;
    return -1;
}

int64_t commandCatalogParseModuleFlags(commandCatalog *cat, char *s) {
    int count, j;
    sds *tokens;
    commandCatalogResetModuleFlags(cat);
    cat->module_flag_str = s;
    if (!s) {
        cat->module_flag_error = 1;
        return -1;
    }
    tokens = sdssplitlen(s,strlen(s)," ",1,&count);
    cat->module_token_count = count;
    for (j = 0; j < count; j++) {
        int64_t mapped;
        cat->module_token = tokens[j];
        mapped = commandCatalogMapModuleFlag(cat, tokens[j]);
        if (mapped < 0) {
            sdsfreesplitres(tokens,count);
            return -1;
        }
        cat->module_flags |= mapped;
    }
    sdsfreesplitres(tokens,count);
    return cat->module_flags;
}

int64_t commandCatalogMapModuleKeySpecFlag(commandCatalog *cat, const char *token) {
    cat->module_token = (char *)token;
    if (!token) {
        cat->module_flag_error = 1;
        return -1;
    }
    if (!strcasecmp(token,"write")) return CMD_KEY_WRITE;
    else if (!strcasecmp(token,"read")) return CMD_KEY_READ;
    else if (!strcasecmp(token,"incomplete")) return CMD_KEY_INCOMPLETE;
    cat->module_flag_error = 1;
    return -1;
}

int64_t commandCatalogParseModuleKeySpecFlags(commandCatalog *cat, const char *s) {
    int count, j;
    sds *tokens;
    cat->module_keyspec_flags = 0;
    cat->module_flag_str = (char *)s;
    cat->module_flag_error = 0;
    if (!s) {
        cat->module_flag_error = 1;
        return -1;
    }
    tokens = sdssplitlen(s,strlen(s)," ",1,&count);
    cat->module_token_count = count;
    for (j = 0; j < count; j++) {
